<?php

define('EPSILON', 1e-6);
define('PIVAL', M_PI);

class Point {
    public $x;
    public $y;

    function __construct($x = 0.0, $y = 0.0) {
        $this->x = $x;
        $this->y = $y;
    }

    function setPoint($x, $y) {
        $this->x = $x;
        $this->y = $y;
    }

    function printPoint($end) {
        if ($end === null) $end = '';
        printf("%.6f %.6f%s", $this->x, $this->y, $end);
    }

    function rot90() {
        return new Point(-$this->y, $this->x);
    }

    function __toString() {
        $xx = (abs($this->x - 0) < EPSILON) ? 0 : $this->x;
        $yy = (abs($this->y - 0) < EPSILON) ? 0 : $this->y;
        return "(" . $xx . "," . $yy . ")";
    }
}

function padd($a, $b) { return new Point($a->x + $b->x, $a->y + $b->y); }
function psub($a, $b) { return new Point($a->x - $b->x, $a->y - $b->y); }
function pmul($a, $val) { return new Point($a->x * $val, $a->y * $val); }
function pdiv($a, $val) { return pmul($a, 1.0 / $val); }

//--------向量运算---------
function PtoV($a, $b) {
    // 两点 所示 向量
    return new Point($b->x - $a->x, $b->y - $a->y);
}

function dMult($a, $b) {
    // 点乘
    return ($a->x * $b->x) + ($a->y * $b->y);
}

function xMult($a, $b) {
    // 叉积，有向面积|a||b|形成的平行四边形
    return $a->x * $b->y - $a->y * $b->x;
}

function VecMod($a) {
    // 模
    return sqrt(dMult($a, $a));
}

function VecMod2($a) {
    // 模平方
    return dMult($a, $a);
}

function Corner2V($a, $b) {
    // 两向量夹角 返回弧度
    return abs(acos(dMult($a, $b) / VecMod($a) / VecMod($b)));
}

function VecUnit($a) {
    // a的单位向量
    return pdiv($a, VecMod($a));
}

function VRotate($v, $alph) {
    // 获得v向量的逆时针旋转alph角度的向量
    $sa = sin($alph);
    $ca = cos($alph);
    return new Point($v->x * $ca - $v->y * $sa, $v->x * $sa + $v->y * $ca);
}

function PRotate($p, $o, $alph) {
    return padd($o, VRotate(PtoV($o, $p), $alph));
}

function GetVV($v) {
    // 获得v向量的垂直向量
    return VRotate($v, PIVAL / 2);
}

function ShadowPOnLine($p, $a, $b) {
    // p在直线|ab|上的垂足
    $ab = PtoV($a, $b);
    $ap = PtoV($a, $p);
    $alph = pdiv(pmul(VecUnit($ab), dMult($ab, $ap)), VecMod($ab));
    return padd($a, $alph);
}

function LineCrossCircle($a, $b, $o, $r) {
    // 直线与圆的交点
    $ret = array();
    $t = ShadowPOnLine($o, $a, $b); // o到直线|ab|的垂足
    $ot = PtoV($o, $t);
    if (VecMod($ot) - $r > EPSILON) return $ret; // 没有交点
    if (abs(VecMod($ot) - $r) < EPSILON) { // 如果相切
        $ret[] = $t;
        return $ret;
    }
    $lr = sqrt($r * $r - VecMod2($ot));
    $ta = padd($t, pmul(VecUnit(PtoV($t, $a)), $lr));
    $tb = padd($t, pmul(VecUnit(PtoV($t, $b)), $lr));
    $ret[] = $ta;
    $ret[] = $tb;
    return $ret;
}

function PointTangentCircle($p, $o, $r) {
    // 圆外一点作两个切线 返回切点
    $x2 = VecMod2(psub($p, $o));
    $d2 = $x2 - $r * $r;
    $ret = array();
    if ($d2 < -EPSILON) return $ret; // 点在圆内
    if ($r <= EPSILON) { // 圆退化为点
        $ret[] = $o;
        $ret[] = $o;
        return $ret;
    }
    $d2 = max($d2, 0.0);
    $q1 = padd($o, pmul(psub($p, $o), ($r * $r / $x2)));
    $q2 = pmul(psub($p, $o)->rot90(), (-$r * sqrt($d2) / $x2));
    $ret[] = psub($q1, $q2);
    $ret[] = padd($q1, $q2);
    return $ret;
}

function POnSeg($p, $a, $b) {
    // 点在线段上
    if (abs(xMult(PtoV($a, $b), PtoV($a, $p))) > EPSILON) return false;
    if (min($a->x, $b->x) > $p->x || $p->x > max($a->x, $b->x)) return false;
    if (min($a->y, $b->y) > $p->y || $p->y > max($a->y, $b->y)) return false;
